use product_source_ingestion::row_delta::*;
use serde_json::{json,Value};
fn result(keys:&[&str],labels:&[&str],version:u64,total:u64)->Value{json!({"subscription":"s","query_generation":1,"sequence":version,"start_rank":0,"version":version,"total_rows":total,"keys":keys,"rows":labels.iter().map(|v|json!({"label":{"state":"value","value":v}})).collect::<Vec<_>>()})}
fn apply(prior:&Value,ops:&[Value])->Value{let mut out=prior.clone();let mut keys=out["keys"].as_array().unwrap().clone();let mut rows=out["rows"].as_array().unwrap().clone();for o in ops {let i=keys.iter().position(|k|k==&o["key"]);match o["type"].as_str().unwrap(){"remove"=>{rows.remove(i.unwrap());keys.remove(i.unwrap());},"insert"=>{let j=o["index"].as_u64().unwrap() as usize;keys.insert(j,o["key"].clone());rows.insert(j,o["row"].clone());},"update"=>{let j=o["index"].as_u64().unwrap() as usize;assert_eq!(keys[j],o["key"]);rows[j]=o["row"].clone();},"move"=>{let a=o["fromIndex"].as_u64().unwrap() as usize;let b=o["toIndex"].as_u64().unwrap() as usize;assert_eq!(keys[a],o["key"]);let k=keys.remove(a);let r=rows.remove(a);keys.insert(b,k);rows.insert(b,r);},_=>panic!()}}out["keys"]=json!(keys);out["rows"]=json!(rows);out}
#[test]fn fixed_interacting_positions(){let a=result(&["a","b","c","d"],&["a","b","c","d"],1,4);let b=result(&["d","e","c","a"],&["d","e","new","a"],9,4);let ops=operations(&a,&b);assert_eq!(ops,json!([{"type":"remove","key":"b"},{"type":"move","key":"d","fromIndex":2,"toIndex":0},{"type":"insert","key":"e","index":1,"row":{"label":{"state":"value","value":"e"}}},{"type":"move","key":"c","fromIndex":3,"toIndex":2},{"type":"update","key":"c","index":2,"row":{"label":{"state":"value","value":"new"}}}]).as_array().unwrap().clone());let applied=apply(&a,&ops);assert_eq!(applied["keys"],b["keys"]);assert_eq!(applied["rows"],b["rows"]);}
#[test]fn sparse_and_total_only_and_navigation(){let keys=(0..100).map(|i|i.to_string()).collect::<Vec<_>>();let refs=keys.iter().map(String::as_str).collect::<Vec<_>>();let a=result(&refs,&refs,1,150);let projection=vec!["label".into()];let (_,base)=batch(None,1,&projection,a.clone(),false);let mut b=a.clone();b["version"]=json!(8);b["rows"][43]["label"]["value"]=json!("change");let(f,base)=batch(Some(&base),1,&projection,b.clone(),false);assert_eq!(f["kind"],"delta");assert_eq!(f["operations"].as_array().unwrap().len(),1);assert_eq!(f["operations"][0]["type"],"update");assert!(f.get("rows").is_none());b["total_rows"]=json!(160);let(f,base)=batch(Some(&base),1,&projection,b.clone(),false);assert_eq!(f["operations"],json!([]));b["start_rank"]=json!(2);let(f,_)=batch(Some(&base),1,&projection,b,false);assert_eq!(f["kind"],"snapshot");}
#[test]fn randomized_bounded_windows(){let mut seed=0x41a53u64;let mut next=||{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1);seed};for _ in 0..3006{let mut a=(0..(next()%24)).map(|i|format!("🦀{i}")).collect::<Vec<_>>();let mut b=(0..(next()%24)).map(|i|format!("🦀{i}")).collect::<Vec<_>>();for v in [&mut a,&mut b]{for i in (1..v.len()).rev(){let j=next() as usize%(i+1);v.swap(i,j);}}let ar=a.iter().map(String::as_str).collect::<Vec<_>>();let br=b.iter().map(String::as_str).collect::<Vec<_>>();let labels=b.iter().map(|s|format!("{s}-{}",next()%3)).collect::<Vec<_>>();let lr=labels.iter().map(String::as_str).collect::<Vec<_>>();let old=result(&ar,&ar,1,a.len() as u64);let target=result(&br,&lr,2,b.len() as u64);let reconstructed=apply(&old,&operations(&old,&target));assert_eq!(reconstructed["keys"],target["keys"]);assert_eq!(reconstructed["rows"],target["rows"]);}}
#[test]fn selected_fields_only(){let full=json!({"rows":[{"id":"secret-key","category":"hidden","quantity":"9223372036854775807","amount":{"coefficient":"123","scale":2},"label":{"state":"missing"}}]});assert_eq!(project(&full,&["quantity".into()]),json!({"keys":["secret-key"],"rows":[{"quantity":"9223372036854775807"}]}));assert!(product_request_admission::admit_projection(Some(&json!(["quantity","quantity"]))).is_err());}
